#!/usr/bin/env node
/* Deterministic generator for the NSO_Repair synthetic fixture set.
 *
 *   node tools/nso_repair_make_fixtures.js            # write fixtures/repair/*.stl
 *   node tools/nso_repair_make_fixtures.js --check    # regenerate to a temp dir and
 *                                                     # diff against what is committed
 *
 * The STLs are committed so the regression suite runs from a clean checkout with
 * no generation step. This script exists so the fixtures can be audited and
 * regenerated byte-for-byte; every value below is a literal, nothing is random.
 */
'use strict';

const fs = require('fs');
const path = require('path');
const os = require('os');
const { writeSTL, readSTL } = require('./nso_stl_io.js');

const OUT = path.join(__dirname, '..', 'fixtures', 'repair');

/* ---------------- primitives ---------------- */

function tri(out, a, b, c) { out.push(a[0], a[1], a[2], b[0], b[1], b[2], c[0], c[1], c[2]); }
function quad(out, a, b, c, d) { tri(out, a, b, c); tri(out, a, c, d); }

/* Axis-aligned closed box, outward-wound, 12 triangles. */
function box(x0, y0, z0, x1, y1, z1) {
  const A = [x0, y0, z0], B = [x1, y0, z0], C = [x1, y1, z0], D = [x0, y1, z0];
  const E = [x0, y0, z1], F = [x1, y0, z1], G = [x1, y1, z1], H = [x0, y1, z1];
  const t = [];
  quad(t, A, D, C, B);   // -Z
  quad(t, E, F, G, H);   // +Z
  quad(t, A, B, F, E);   // -Y
  quad(t, C, D, H, G);   // +Y
  quad(t, A, E, H, D);   // -X
  quad(t, B, C, G, F);   // +X
  return t;
}

/* Pyramid: apex + a 4-corner base ring. Winding is fixed up afterwards so the
 * solid always comes out positively oriented. */
function pyramid(apex, ring) {
  const t = [];
  for (let i = 0; i < 4; i++) tri(t, apex, ring[i], ring[(i + 1) % 4]);
  quad(t, ring[0], ring[3], ring[2], ring[1]);
  return orientPositive(t);
}

function signedVolume(flat) {
  let v = 0;
  for (let i = 0; i < flat.length; i += 9) {
    const a = flat.slice(i, i + 3), b = flat.slice(i + 3, i + 6), c = flat.slice(i + 6, i + 9);
    v += a[0] * (b[1] * c[2] - b[2] * c[1]) - a[1] * (b[0] * c[2] - b[2] * c[0]) + a[2] * (b[0] * c[1] - b[1] * c[0]);
  }
  return v / 6;
}

function orientPositive(flat) {
  if (signedVolume(flat) >= 0) return flat;
  const out = [];
  for (let i = 0; i < flat.length; i += 9) {
    out.push(flat[i], flat[i + 1], flat[i + 2],
             flat[i + 6], flat[i + 7], flat[i + 8],
             flat[i + 3], flat[i + 4], flat[i + 5]);
  }
  return out;
}

/* The shared 20 mm cube: origin-centred, 12 triangles, volume exactly 8000. */
function cube20() { return box(-10, -10, -10, 10, 10, 10); }

/* Named corners of cube20(), so the defect fixtures below can refer to the same
 * edge the cube's own triangles use. */
const CUBE = {
  A: [-10, -10, -10], B: [10, -10, -10], C: [10, 10, -10], D: [-10, 10, -10],
  E: [-10, -10, 10], F: [10, -10, 10], G: [10, 10, 10], H: [-10, 10, 10]
};

/* ---------------- the six defect fixtures ---------------- */

/* 1. hole — the cube with one bottom triangle deleted. One 3-edge boundary loop. */
function fxHole() {
  const t = cube20();
  return t.slice(0, 0).concat(t.slice(9)); // drop triangle 0
}

/* 2. exact duplicate — triangle 0 present twice, same winding. */
function fxDupExact() {
  const t = cube20();
  return t.concat(t.slice(0, 9));
}

/* 3. real + reversed duplicate — triangle 0 present twice, second one flipped.
 *    Both copies are "real" geometry; only the flipped one must go, and which
 *    one is flipped has to be worked out from the surrounding winding. */
function fxDupReversed() {
  const t = cube20();
  const t0 = t.slice(0, 9);
  return t.concat([t0[0], t0[1], t0[2], t0[6], t0[7], t0[8], t0[3], t0[4], t0[5]]);
}

/* 4. floating flap — one extra triangle hanging off cube edge F-G, sticking out
 *    into free space. Makes F-G a 3-use non-manifold edge and adds two boundary
 *    edges that belong to nothing. */
function fxFlap() {
  const t = cube20();
  tri(t, CUBE.F, CUBE.G, [18, 0, 18]);
  return t;
}

/* 5. T-junction — the top face's triangle (E,F,G) is split at M, the midpoint of
 *    edge F-G, but the +X face still carries F-G whole. M is left sitting on the
 *    interior of that edge: 3 boundary edges, nothing welds them. */
function fxTJunction() {
  const t = [];
  const M = [10, 0, 10]; // midpoint of F(10,-10,10) - G(10,10,10)
  const { A, B, C, D, E, F, G, H } = CUBE;
  quad(t, A, D, C, B);   // -Z
  tri(t, E, F, M); tri(t, E, M, G); tri(t, E, G, H);   // +Z, split at M
  quad(t, A, B, F, E);   // -Y
  quad(t, C, D, H, G);   // +Y
  quad(t, A, E, H, D);   // -X
  quad(t, B, C, G, F);   // +X, still carries F-G whole
  return t;
}

/* 6. near-duplicate vertices — the cube, but every vertex slot is jittered by a
 *    fixed pattern of +/-2e-5 mm. No two copies of a corner are bit-equal, so an
 *    exact-match weld leaves 36 loose vertices and 36 open edges; a 1e-4 weld
 *    puts them back together. The jitter is a repeating literal sequence, not a
 *    random draw, so the file is reproducible. */
function fxNearDupVertex() {
  const t = cube20();
  const J = [2e-5, -2e-5, 1e-5, -1e-5, 2e-5, -2e-5, 1e-5, -1e-5, -2e-5, 2e-5, -1e-5, 1e-5];
  return t.map((v, i) => v + J[i % J.length]);
}

/* ---------------- the two pinch fixtures ---------------- */

/* 7. safe-angle 2-sheet pinch — two square pyramids apex to apex at the origin.
 *    The two sheets meet at a wide, convex angle (each cone opens directly away
 *    from the other), so nudging each apex back into its own cone separates them
 *    and nothing collides. */
function fxPinchSafe() {
  const up = pyramid([0, 0, 0], [[-6, -6, 10], [6, -6, 10], [6, 6, 10], [-6, 6, 10]]);
  const dn = pyramid([0, 0, 0], [[-6, -6, -10], [6, -6, -10], [6, 6, -10], [-6, 6, -10]]);
  return up.concat(dn);
}

/* 8. tight-angle 2-sheet pinch — a box with a pyramidal pit sunk into its top
 *    face, and a separate spike standing coaxially in that pit. Both apexes are
 *    the same point, and that is the only place the two solids touch: before
 *    repair the file is watertight with zero self-intersections.
 *
 *    The pit's fan is reflex, so "back into my own shell" points UP, out of the
 *    pit — which is exactly where the spike is. The two fans therefore nudge
 *    along the SAME direction (a 0 degree pinch angle, against 180 degrees for
 *    fixture 7), the pit apex ends up inside the spike, and the pit walls cut
 *    across it: 12 intersecting triangle pairs. Nothing local to the vertex says
 *    so in advance, which is what the gate is for. */
function fxPinchTight() {
  const t = [];
  const B = 8, H = 12, Dp = 9;         // half-width, box depth, pit depth
  const O = [0, 0, -Dp];
  const T = [[-B, -B, 0], [B, -B, 0], [B, B, 0], [-B, B, 0]];
  const L = [[-B, -B, -H], [B, -B, -H], [B, B, -H], [-B, B, -H]];

  // pit: top face replaced by four walls running down to O
  for (let i = 0; i < 4; i++) tri(t, T[i], O, T[(i + 1) % 4]);
  // bottom
  quad(t, L[0], L[1], L[2], L[3]);
  // sides
  for (let i = 0; i < 4; i++) {
    const a = T[i], b = T[(i + 1) % 4], c = L[(i + 1) % 4], d = L[i];
    quad(t, a, b, c, d);
  }
  const pit = orientPositive(t);

  // spike: apex at O, coaxial with the pit, comfortably clear of its walls
  const Ls = 7, s = 1.2, tau = 0;
  const u = [Math.sin(tau), 0, Math.cos(tau)];
  const e1 = [Math.cos(tau), 0, -Math.sin(tau)];
  const e2 = [0, 1, 0];
  const ctr = [O[0] + u[0] * Ls, O[1] + u[1] * Ls, O[2] + u[2] * Ls];
  const ring = [[-1, -1], [1, -1], [1, 1], [-1, 1]].map(([p, q]) =>
    [ctr[0] + e1[0] * p * s + e2[0] * q * s,
     ctr[1] + e1[1] * p * s + e2[1] * q * s,
     ctr[2] + e1[2] * p * s + e2[2] * q * s]);
  const spike = pyramid(O, ring);

  return pit.concat(spike);
}

/* ---------------- driver ---------------- */

const FIXTURES = [
  ['synth_hole.stl', fxHole, 'cube20 minus one triangle'],
  ['synth_dup_exact.stl', fxDupExact, 'cube20 with triangle 0 duplicated'],
  ['synth_dup_reversed.stl', fxDupReversed, 'cube20 with triangle 0 duplicated reversed'],
  ['synth_flap.stl', fxFlap, 'cube20 with a floating flap on edge F-G'],
  ['synth_tjunction.stl', fxTJunction, 'cube20 with a T-junction on edge F-G'],
  ['synth_near_dup_vertex.stl', fxNearDupVertex, 'cube20 with +/-2e-5 vertex jitter'],
  ['synth_pinch_2sheet_safe.stl', fxPinchSafe, '2-sheet pinch, wide convex angle'],
  ['synth_pinch_2sheet_tight.stl', fxPinchTight, '2-sheet pinch, tight angle']
];

function build(dir) {
  fs.mkdirSync(dir, { recursive: true });
  const rows = [];
  for (const [name, fn, header] of FIXTURES) {
    const flat = fn();
    const raw = new Float32Array(flat);
    const n = writeSTL(path.join(dir, name), raw, 'NSO_Repair fixture: ' + header);
    rows.push([name, n]);
  }
  return rows;
}

function main() {
  const check = process.argv.includes('--check');
  if (!check) {
    for (const [name, n] of build(OUT)) console.log('wrote', name, n, 'tris');
    return 0;
  }
  const tmp = fs.mkdtempSync(path.join(os.tmpdir(), 'nso-fx-'));
  build(tmp);
  let bad = 0;
  for (const [name] of FIXTURES) {
    const a = fs.readFileSync(path.join(OUT, name));
    const b = fs.readFileSync(path.join(tmp, name));
    const same = a.equals(b);
    if (!same) bad++;
    console.log((same ? 'ok   ' : 'DRIFT') + '  ' + name);
  }
  fs.rmSync(tmp, { recursive: true, force: true });
  if (bad) console.error('\n' + bad + ' committed fixture(s) do not match the generator');
  return bad ? 1 : 0;
}

process.exit(main());
